import{_ as n,o as r,c as t,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/archiv/fehlermeldung-inkompatibilitaet-reportdesigner.png",m=JSON.parse('{"title":"Reports zwischen SchILD-NRW 2 und 3 umstellen","description":"","frontmatter":{"title":"Reports zwischen SchILD-NRW 2 und 3 umstellen","source_pageid":1547,"source_revision":6562},"headers":[],"relativePath":"reporting/archiv/kompatibilitaet-der-reports-in-schild-nrw-2-und-schild-nrw-3.md","filePath":"reporting/archiv/kompatibilitaet-der-reports-in-schild-nrw-2-und-schild-nrw-3.md"}'),a={name:"reporting/archiv/kompatibilitaet-der-reports-in-schild-nrw-2-und-schild-nrw-3.md"};function s(l,e,o,u,h,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="reports-zwischen-schild-nrw-2-und-3-umstellen" tabindex="-1">Reports zwischen SchILD-NRW 2 und 3 umstellen <a class="header-anchor" href="#reports-zwischen-schild-nrw-2-und-3-umstellen" aria-label="Permalink to &quot;Reports zwischen SchILD-NRW 2 und 3 umstellen&quot;">​</a></h1><p>Reports aus SchILD-NRW 2 können wegen anderer Komponenten und Datenquellen Anpassungen benötigen. Die folgenden Abschnitte unterscheiden die Umstellung auf SchILD-NRW 3 vom umgekehrten Einsatz.</p><h2 id="grundlagen-und-voraussetzungen" tabindex="-1">Grundlagen und Voraussetzungen <a class="header-anchor" href="#grundlagen-und-voraussetzungen" aria-label="Permalink to &quot;Grundlagen und Voraussetzungen&quot;">​</a></h2><p>Der Reportdesigner unterliegt als eigenständige Programmkomponente ebenfalls einem Updatezyklus. Die nahtlose Integration in SchILD-NRW 3 erfordert zu jedem Update vielfältige Anpassungen des Reportdesigners. Mit dem Erscheinen der Produktivversion von SchILD-NRW 3 wird die Version 22 des Reportdesigners ausgeliefert, während in SchILD-NRW 2 die Version 15 verwendet wird. Durch die Funktionszunahme der neueren Versionen des Reportdesigners, werden zusätzliche Daten in einem Report abgespeichert.</p><h2 id="entfallene-komponenten-und-ihre-alternativen" tabindex="-1">Entfallene Komponenten und ihre Alternativen <a class="header-anchor" href="#entfallene-komponenten-und-ihre-alternativen" aria-label="Permalink to &quot;Entfallene Komponenten und ihre Alternativen&quot;">​</a></h2><p>Der Reportdesigner in SchILD-NRW 2 enthält eine Zusatzkomponente mit dem Namen &quot;GridPack&quot;. Diese enthält die Elemente &quot;TableGrid&quot;, &quot;DBTableGrid&quot;, &quot;CheckBox&quot; und &quot;CrossTable&quot;. Diese Zusatzkomponente ist im Reportdesigner von SchILD-NRW 3 nicht mehr enthalten. Durch den Funktionszuwachs des neuen Reportdesigners ist diese Zusatzkomponente jedoch nicht mehr notwendig. Im neuen Reportdesigner selbst ist das Element SimpleGrid weggefallen und wird von dem Element TableGrid abgelöst. Das Element &quot;RotatedLabel&quot; ist ebenfalls weggefallen, da jedes Label die Eigenschaft der Rotation erhalten hat.</p><table tabindex="0"><thead><tr><th>Fällt weg</th><th>Alternativen</th></tr></thead><tbody><tr><td>GridPack TableGrid</td><td>TableGrid</td></tr><tr><td>GridPack DBTableGrid</td><td>TableGrid</td></tr><tr><td>SimpleGrid</td><td>TableGrid</td></tr><tr><td>GridPack CheckBox</td><td>CheckBox</td></tr><tr><td>GridPack CheckBox</td><td>DBCheckBox</td></tr><tr><td>GridPack CrossTable</td><td>Kreuztabelle</td></tr><tr><td>RotatedLabel</td><td>normale Label können rotiert werden</td></tr></tbody></table><h2 id="geanderte-vordefinierte-datenquellen" tabindex="-1">Geänderte vordefinierte Datenquellen <a class="header-anchor" href="#geanderte-vordefinierte-datenquellen" aria-label="Permalink to &quot;Geänderte vordefinierte Datenquellen&quot;">​</a></h2><p>Aufgrund der geänderten Datenstruktur der Datenbank des SVWS-Servers mussten einige Änderungen an den vordefinierten Datenquellen des Reportdesigners vorgenommen werden. Hierdurch sind manche Datenquellen und Datenfelder weggefallen und andere hinzugekommen. So ist z.B. die Datenquelle &quot;Erzieherfunktion&quot; mit allen Datenfeldern weggefallen. In der Datenquelle hingegen sind die neuen Datenfelder &quot;AlleVornamen&quot; und &quot;Rufname&quot; hinzugekommen.</p><h2 id="eigene-datenquellen" tabindex="-1">Eigene Datenquellen <a class="header-anchor" href="#eigene-datenquellen" aria-label="Permalink to &quot;Eigene Datenquellen&quot;">​</a></h2><p>Die Datenbankstruktur von SchILD-NRW 2 und SchILD-NRW 3 unterscheidet sich grundlegend. Im neuen Reportdesigner müssen entsprechend eigene Datenquellen auf andere Art und Weise definiert werden.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><p><a href="/bilder/archiv/fehlermeldung-inkompatibilitaet-reportdesigner.png"><img src="'+d+'" alt="Beispiel einer Fehlermeldung" loading="lazy"></a></p><p><em>Beispiel einer Fehlermeldung</em></p><p>Sollen Reports aus SchILD-NRW 2 in SchILD-NRW 3 verwendet werden, so ist vorab zu untersuchen, ob diese Komponenten aus dem GridPack oder eigene Datenquellen verwenden. Wenn dies der Fall ist, muss der Report angepasst werden. Hierzu kann dieser im Reportdesigner von SchILD-NRW 3 geöffnet werden. Beim Öffnen kommt es zu einer Fehlermeldung oder mehreren Fehlermeldungen. Im Fenster der Fehlermeldung kann dann die Schaltfläche &quot;Alles ignorieren&quot; angeklickt werden. Hierdurch werden Elemente aus dem GridPack von Reportdesigner entfernt. Alternative Elemente müssen entsprechend als Ersatz eingefügt und eigene Datenquellen angepasst oder neu definiert werden.</p><h2 id="reports-aus-schild-nrw-2-in-schild-nrw-3-verwenden" tabindex="-1">Reports aus SchILD-NRW 2 in SchILD-NRW 3 verwenden <a class="header-anchor" href="#reports-aus-schild-nrw-2-in-schild-nrw-3-verwenden" aria-label="Permalink to &quot;Reports aus SchILD-NRW 2 in SchILD-NRW 3 verwenden&quot;">​</a></h2><p>Wird ein Report aus SchILD-NRW 2 aufgerufen, der weder Elemente aus dem GridPack enthält noch eigene Datenquellen nutzt, so kann dieser in SchiLD_NRW 3 ohne Einschränkungen aufgerufen werden. Es ist trotzdem empfehlenswert, den Report einmalig im Reportdesigner zu öffnen und in der neuen Version zu speichern.</p><p>Enthält der Report Elemente aus dem GridPack, so kommt es beim Aufruf zu einer Fehlermeldung. Wenn die Fehlermeldungen ignoriert werden, wird der Ausdruck durchgeführt bzw. die Voransicht angezeigt. Die nicht mehr vorhandenen Elemente werden jedoch nicht mehr angezeigt. Solange ein solcher Report nicht einmalig im Reportdesigner geöffnet und in der neuen Version abgespeichert wird, kommt es bei jedem erneuten Aufruf zu der Fehlermeldung.</p><p>Enthält der Report eigene Datenquellen, welche in SchILD-NRW 3 nicht existieren, so kommt es zu einer Fehlermeldung und der Report kann nicht gedruckt werden. Es ist dann notwendig, den Report im Reportdesigner zu öffnen und die Datenquellen anzupassen.</p><h2 id="reports-aus-schild-nrw-3-in-schild-nrw-2-verwenden" tabindex="-1">Reports aus SchILD-NRW 3 in SchILD-NRW 2 verwenden <a class="header-anchor" href="#reports-aus-schild-nrw-3-in-schild-nrw-2-verwenden" aria-label="Permalink to &quot;Reports aus SchILD-NRW 3 in SchILD-NRW 2 verwenden&quot;">​</a></h2><p>Hierzu liegen keine Erfahrungen vor. Es ist aber zu erwarten, dass es zu ähnlichen Auswirkungen kommt, wie vorab beschrieben. Insbesondere bei erweiterten Funktionen von Elementen, die in beiden Reportdesignern vorhanden sind, sind Probleme zu erwarten. Ein Beispiel wäre hier die neue Möglichkeit, Label zu rotieren. Zudem gibt es Unterschiede zwischen den vordefinierten Pipelines in SchILD-NRW 2 und SchILD-NRW 3. Elemente, welche auf Daten dieser Pipelines zugreifen, finden keine passende Definition.</p><p>Es ist deshalb zu empfehlen, vorhandene Reports aus SchILD-NRW 2 an SchILD-NRW 3 anzupassen, oder noch besser auf die optimierten Reports aus der Basisreportsammlung umzusteigen. Es ist jedoch nicht zu empfehlen, Reports aus SchILD-NRW 3 in SchILD-NRW 2 zu verwenden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kompatibilit%C3%A4t_der_Reports_in_SchILD-NRW_2_und_SchILD-NRW_3" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6562.</p>',24)])])}const g=n(a,[["render",s]]);export{m as __pageData,g as default};
